cd /filesystem/final_batch4__structural_task7_roof_deck_design__blind && python3 -c "
import json
for f in ['project/20_site/usgs_design_maps/USGS_ASCE7-22_RC-III_SiteClass-D_46.6832_-111.9756.json','project/20_site/usgs_design_maps/USGS_ASCE7-16_RC-II_SiteClass-C_46.6832_-111.9756_(2019_preliminary).json']:
    d = json.load(open(f))
    print('=====', f)
    def walk(o, pre=''):
        if isinstance(o, dict):
            for k,v in o.items():
                walk(v, pre+'.'+k)
        elif isinstance(o, list):
            if len(o) > 6 and all(not isinstance(x,(dict,list)) for x in o):
                print(pre, '[list len', len(o), ']', o[:4])
            else:
                for i,v in enumerate(o):
                    walk(v, pre+'[%d]'%i)
        else:
            print(pre, '=', o)
    walk(d)
" | head -150

