import re, html
x = open('library/29_CFR_1926_Subpart_R_Steel_Erection_eCFR.xml').read()
# split into sections
secs = re.split(r'<DIV8 ', x)
for s in secs:
    m = re.search(r'N="(1926\.7\d\d)"', s)
    if not m: continue
    if m.group(1) in ('1926.754','1926.757','1926.751'):
        t = re.sub(r'<[^>]+>', ' ', s)
        t = html.unescape(t)
        t = re.sub(r'[ \t]+', ' ', t)
        t = re.sub(r'\n\s*\n+', '\n', t)
        if m.group(1)=='1926.754':
            print(t[:9000])
        elif m.group(1)=='1926.751':
            # print definitions related to decking
            for line in t.split('\n'):
                if 'deck' in line.lower() or 'opening' in line.lower() or 'hole' in line.lower():
                    print('DEF:', line[:600])
