from common import *
# A drift band: dict with face position, direction of decay, lateral extent, peak, width
def obstruction_bands(name, rect, h, lu_rule='edge'):
    x0,x1,y0,y1 = rect
    hc = h-HB
    bands=[]
    if hc<=2.0: return bands
    # wind from W (blowing +x): windward face W at x0, drift extends to -x; leeward face E at x1 extends +x
    for wdir in ('W','E','S','N'):
        if wdir=='W':
            lu_w = x0-0.0; lu_l = x1-x0
            faces=[('W',x0,-1,0.75*hd_fun(lu_w),'windward',lu_w),('E',x1,+1,hd_fun(lu_l),'leeward',lu_l)]
            lat=(y0,y1); axis='x'
        elif wdir=='E':
            lu_w = BX-x1; lu_l = x1-x0
            faces=[('E',x1,+1,0.75*hd_fun(lu_w),'windward',lu_w),('W',x0,-1,hd_fun(lu_l),'leeward',lu_l)]
            lat=(y0,y1); axis='x'
        elif wdir=='S':
            lu_w = y0-0.0; lu_l = y1-y0
            faces=[('S',y0,-1,0.75*hd_fun(lu_w),'windward',lu_w),('N',y1,+1,hd_fun(lu_l),'leeward',lu_l)]
            lat=(x0,x1); axis='y'
        else:
            lu_w = BY-y1; lu_l = y1-y0
            faces=[('N',y1,+1,0.75*hd_fun(lu_w),'windward',lu_w),('S',y0,-1,hd_fun(lu_l),'leeward',lu_l)]
            lat=(x0,x1); axis='y'
        for face,pos,sgn,hdr,kind,lu in faces:
            peak,w = drift_shape(hdr,hc)
            bands.append(dict(obs=name,wind=wdir,face=face,axis=axis,pos=pos,sgn=sgn,lat=lat,peak=peak,w=w,kind=kind,lu=max(lu,20),hdr=hdr,hc=hc))
    return bands

def parapet_bands():
    hc = PAR_H-HB
    bands=[]
    # wind from S arrives at N parapet inside face (y = BY-PAR_T), drift extends -y; lu = BY
    specs=[('S','N',BY-PAR_T,-1,'y',(0,BX),BY),('N','S',PAR_T,+1,'y',(0,BX),BY),
           ('W','E',BX-PAR_T,-1,'x',(0,BY),BX),('E','W',PAR_T,+1,'x',(0,BY),BX)]
    for wdir,face,pos,sgn,axis,lat,lu in specs:
        hdr=0.75*hd_fun(lu)
        peak,w=drift_shape(hdr,hc)
        bands.append(dict(obs='PARAPET-'+face,wind=wdir,face=face,axis=axis,pos=pos,sgn=sgn,lat=lat,peak=peak,w=w,kind='windward',lu=lu,hdr=hdr,hc=hc))
    return bands

def band_value(b, X, Y):
    """surcharge of band at points X,Y (arrays)"""
    if b['axis']=='x':
        d = (X-b['pos'])*b['sgn']; lat = Y
    else:
        d = (Y-b['pos'])*b['sgn']; lat = X
    inlat = (lat>=b['lat'][0]-1e-9)&(lat<=b['lat'][1]+1e-9)
    val = np.where((d>=-1e-9)&(d<=b['w']+1e-9)&inlat, b['peak']*(1-np.clip(d,0,None)/b['w']), 0.0)
    return val

GROUPS={'S02':['MEP-PH-1'],'S04':[k for k in OBS if k.startswith('RTU') or k.startswith('SCR')]}
def scenario_bands(sc):
    if sc=='S03': return parapet_bands()
    bl=[]
    for k in GROUPS[sc]:
        x0,x1,y0,y1,h=OBS[k]
        bl+=obstruction_bands(k,(x0,x1,y0,y1),h)
    return bl
if __name__=='__main__':
    for sc in ('S02','S03','S04'):
        for b in scenario_bands(sc):
            if b['peak']>0:
                print(sc,b['obs'],b['wind'],b['face'],b['kind'],'lu=%.1f hdr=%.3f hc=%.3f peak=%.1f w=%.2f'%(b['lu'],b['hdr'],b['hc'],b['peak'],b['w']))
