from drifts import *
NX, NY = 40, 30
def opening_cells():
    m = np.zeros((NY,NX),bool)
    for k,(x0,x1,y0,y1) in OPENINGS.items():
        for j in range(NY):
            for i in range(NX):
                cx0,cx1,cy0,cy1 = 6*i,6*i+6,6*j,6*j+6
                if cx0 < x1 and cx1 > x0 and cy0 < y1 and cy1 > y0:
                    m[j,i]=True
    return m
def cell_drift(sc, mode='max', closed=False, n=25):
    """max drift surcharge in each cell for scenario sc"""
    bands = scenario_bands(sc)
    out = np.zeros((NY,NX))
    eps = 0.0 if closed else 1e-6
    s = np.linspace(eps, 6-eps, n)
    for j in range(NY):
        for i in range(NX):
            X,Y = np.meshgrid(6*i+s, 6*j+s)
            best = np.zeros_like(X)
            for wdir in 'WESN':
                bl=[b for b in bands if b['wind']==wdir and b['peak']>0]
                if not bl: continue
                if mode=='max':
                    v = np.max([band_value(b,X,Y) for b in bl],axis=0)
                else:
                    v = np.sum([band_value(b,X,Y) for b in bl],axis=0)
                best = np.maximum(best,v)
            out[j,i]=best.max()
    return out
def req_gage(drift):
    lim = {22:min(w_allow(22)-COLL-DECK_W[22], w_defl(22))-PF, 20:min(w_allow(20)-COLL-DECK_W[20], w_defl(20))-PF, 18:min(w_allow(18)-COLL-DECK_W[18], w_defl(18))-PF}
    g = np.full(drift.shape, 22)
    g[drift>lim[22]+1e-9]=20
    g[drift>lim[20]+1e-9]=18
    g[drift>lim[18]+1e-9]=16
    return g
def show(g, om):
    ch={22:'.',20:'o',18:'#',16:'X'}
    for j in range(NY-1,-1,-1):
        row=''.join('O' if om[j,i] else ch[int(g[j,i])] for i in range(NX))
        print('%3d %s'%(6*j,row))
    print('    '+''.join(str((i*6//10)%10) if (i*6)%30==0 else ' ' for i in range(NX)))
if __name__=='__main__':
    om = opening_cells()
    import sys
    for mode in ('max','sum'):
        for closed in (False,True):
            G = np.full((NY,NX),22)
            D = {}
            for sc in ('S02','S03','S04'):
                D[sc]=cell_drift(sc,mode,closed)
                G = np.minimum(G, 0) if False else np.where(req_gage(D[sc])<G, req_gage(D[sc]), G)
            print('==== mode',mode,'closed',closed, 'max drift', {k:round(v.max(),1) for k,v in D.items()})
            show(G, om)
            print('cells 18:',int((G==18).sum()),'20:',int((G==20).sum()),'16:',int((G==16).sum()))
