from fem import *
from cells import opening_cells
OM = opening_cells()
WX, WY = 118.0, 152.0
WSEIS = 18.0 + (0.2*PF if PF>30 else 0.0)
FPX = SDS_IE_R = 0.44*1.25/3.25*WSEIS*240*180/1000.0
def line_forces(res, bars):
    """returns dict line-> list of (pos_mid, total_force, edge_force, member_force)"""
    bf=res['bar_forces']
    out={}
    tmp={}
    for k,(n1,n2,EA,L,typ,lid) in enumerate(bars):
        if lid[0]=='x':
            if lid[1] not in (0.0,240.0): continue
            pos=(YS[n1//NXn]+YS[n2//NXn])/2
        else:
            if lid[1] not in (0.0,180.0): continue
            pos=(XS[n1%NXn]+XS[n2%NXn])/2
        key=(lid,pos)
        d=tmp.setdefault(key,{'total':0.0,'edge':0.0,'member':0.0})
        d['total']+=bf[k]
        if typ=='edge': d['edge']+=bf[k]
        else: d['member']+=bf[k]
    return tmp
def summarize(res, bars, u, direction, amp=1.0):
    lf=line_forces(res,bars)
    if direction=='x':
        chord_lines=[('x',0.0),('x',240.0)]
        frames=[(n,v) for n,v in FRAMES.items() if v[0]=='X']
    else:
        chord_lines=[('y',0.0),('y',180.0)]
        frames=[(n,v) for n,v in FRAMES.items() if v[0]=='Y']
    chord={'total':0,'edge':0,'member':0}
    for (lid,pos),d in lf.items():
        if lid in chord_lines:
            for kk in chord: chord[kk]=max(chord[kk],abs(d[kk]))
    coll={'total':0,'edge':0,'member':0}
    for (lid,pos),d in lf.items():
        for n,(dr,line,f,t,k) in frames:
            ltype = 'y' if dr=='X' else 'x'
            if lid==(ltype,line) and (f-30-1e-6)<=pos<=(t+30+1e-6):
                for kk in coll: coll[kk]=max(coll[kk],abs(d[kk])*amp)
    q=np.abs(res['q_plf']).max()
    # deflection measures
    comp = 0 if direction=='x' else 1
    ud = u[comp::2]
    ff=res['frame_forces']
    drifts=[ff[n]/v[4] for n,v in frames]
    avg_drift=np.mean(np.abs(drifts))
    return dict(q=q, chord=chord, coll=coll, umax=np.abs(ud).max(), avg_drift=avg_drift, frames={n:round(ff[n],1) for n,_ in frames}, reg=res['reg_frac'])
def run_case(cellG, case, edge_mode='separate', ecc_mode='linear'):
    PGm=panel_G(cellG)
    kind, d, ecc = case
    if kind=='W':
        F=loads_wind(d, WX if d=='x' else WY, ecc_ft=ecc, factor=(0.75 if ecc!=0 else 1.0))
    else:
        F=loads_seismic(d, FPX, ecc_ft=ecc, mode=ecc_mode)
    u,bars,springs,K=solve(PGm,F,edge_mode)
    res=post(u,bars,springs,PGm,F)
    return res,bars,u,F
if __name__=='__main__':
    print('WSEIS',WSEIS,'FPX',FPX)
    for G in (10,15,20,25,30,35,40):
        cellG=np.full((30,40),float(G)); cellG[OM]=0
        for case in (('W','x',0),('W','y',0),('E','x',9.0),('E','x',-9.0),('E','y',12.0),('E','y',-12.0)):
            res,bars,u,F=run_case(cellG,case)
            s=summarize(res,bars,u,case[1])
            print(G, case, 'q=%.0f umax=%.2f avgdrift=%.2f chord(tot/edge)=%.1f/%.1f coll(tot/edge/mem)=%.1f/%.1f/%.1f'%(s['q'],s['umax'],s['avg_drift'],s['chord']['total'],s['chord']['edge'],s['coll']['total'],s['coll']['edge'],s['coll']['member']), s['frames'])
