import numpy as np, itertools, json
from common import *
from catalog import sn_formula, gp_formula
from cells import cell_drift, opening_cells, NX, NY
import fem
from fem import panel_G, loads_wind, loads_seismic, solve, post, FRAMES, NXn, NYn, XS, YS, nid
OM = opening_cells()
# ---------------- cached demand maps ----------------
import os, pickle
CACHE='/work/demand_cache.pkl'
def build_demands(closed=False):
    key='closed' if closed else 'strict'
    if os.path.exists(CACHE):
        d=pickle.load(open(CACHE,'rb'))
        if key in d: return d[key]
    else: d={}
    dm={sc:cell_drift(sc,'max',closed) for sc in ('S02','S03','S04')}
    d[key]=dm
    pickle.dump(d,open(CACHE,'wb'))
    return dm
# uplift zones (cell based, worst point in cell)
QH=0.00256*1.04*1.0*0.85*1.0*115**2
A_ZONE=max(min(0.1*180,0.4*32),0.04*180,3.0)
UPL={'3':101.2,'2':74.2,'1':47.3,'1p':32.3}
def uplift_map():
    a=A_ZONE
    U=np.zeros((NY,NX))
    for j in range(NY):
        for i in range(NX):
            x0,x1,y0,y1=6*i,6*i+6,6*j,6*j+6
            # min distance from cell to each edge
            dxw=x0; dxe=BX-x1; dys=y0; dyn=BY-y1
            dx=min(dxw,dxe); dy=min(dys,dyn); dmin=min(dx,dy)
            if dx<a and dy<a: U[j,i]=UPL['3']
            elif dmin<a: U[j,i]=UPL['2']
            elif dmin<2*a: U[j,i]=UPL['1']
            else: U[j,i]=UPL['1p']
    return U
UMAP=uplift_map()
def boundary_cells():
    B=np.zeros((NY,NX),bool)
    B[0,:]=B[-1,:]=True; B[:,0]=B[:,-1]=True
    # neighbours of opening cells (8-neighbourhood)
    for j in range(NY):
        for i in range(NX):
            if OM[j,i]: continue
            for dj in (-1,0,1):
                for di in (-1,0,1):
                    jj,ii=j+dj,i+di
                    if 0<=jj<NY and 0<=ii<NX and OM[jj,ii]: B[j,i]=True
    return B
BMAP=boundary_cells()
# ---------------- capacities ----------------
def grav_caps(g):
    wa=w_allow(g); wd=w_defl(g)
    return wa, wd
def uplift_cap(g,n):
    return 0.5*PNOV[g]*n/18.0 + 0.9*(DECK_W[g]+ROOFING)
def pattern_str(n): return '36/%d'%n
# ---------------- design representation ----------------
# zones: dict zone_id -> dict(g=..., n=..., typ=..., ns=..., rects=[(x0,y0,x1,y1),...]) in ft
def cell_assign(zones):
    Z=np.full((NY,NX),None,dtype=object)
    errs=[]
    for zid,z in zones.items():
        for (x0,y0,x1,y1) in z['rects']:
            for v in (x0,y0,x1,y1):
                if abs(v/6-round(v/6))>1e-9: errs.append('rect off grid %s %s'%(zid,(x0,y0,x1,y1)))
            for j in range(int(y0//6),int(y1//6)):
                for i in range(int(x0//6),int(x1//6)):
                    if Z[j,i] is not None: errs.append('overlap at cell %d,%d (%s,%s)'%(i,j,Z[j,i],zid))
                    Z[j,i]=zid
    for j in range(NY):
        for i in range(NX):
            if not OM[j,i] and Z[j,i] is None: errs.append('uncovered cell x=%d y=%d'%(6*i,6*j))
            if OM[j,i] and Z[j,i] is not None: errs.append('opening cell covered x=%d y=%d by %s'%(6*i,6*j,Z[j,i]))
    return Z, errs
def rules(zones):
    errs=[]
    gages=set(z['g'] for z in zones.values())
    pats=set((z['n'],z['typ'],z['ns']) for z in zones.values())
    nrect=sum(len(z['rects']) for z in zones.values())
    if len(gages)>2: errs.append('more than 2 gages')
    if len(pats)>3: errs.append('more than 3 patterns %s'%pats)
    if len(zones)>12: errs.append('more than 12 zones')
    if nrect>14: errs.append('more than 14 rectangles (%d)'%nrect)
    for zid,z in zones.items():
        if z['g'] not in (22,20,18): errs.append('%s gage %s not available'%(zid,z['g']))
        if z['typ']=='BP' and z['g']<20: errs.append('%s BP on gage %d'%(zid,z['g']))
        if z['ns']<2 or z['ns']>5: errs.append('%s ns out of range'%zid)
        if z['n'] not in (4,5,7,9): errs.append('%s n invalid'%zid)
    Z,e2=cell_assign(zones); errs+=e2
    # boundary minimum
    for zid,z in zones.items():
        touches = any(BMAP[j,i] for j in range(NY) for i in range(NX) if Z[j,i]==zid)
        z['_boundary']=touches
        if touches and (z['n']<7 or z['ns']<3): errs.append('%s touches boundary/opening but has 36/%d ns=%d'%(zid,z['n'],z['ns']))
    return Z, errs
# ---------------- gravity / uplift checks ----------------
def check_gravity(zones, Z, dm):
    out={}; errs=[]
    for zid,z in zones.items():
        g=z['g']; wa,wd=grav_caps(g); D=COLL+DECK_W[g]
        cells=[(j,i) for j in range(NY) for i in range(NX) if Z[j,i]==zid]
        worst={'S01':D+LR}
        for sc in ('S02','S03','S04'):
            worst[sc]=D+PF+max(dm[sc][j,i] for j,i in cells)
        # deflection uses live/snow only
        sl=max(LR, max(PF+max(dm[sc][j,i] for j,i in cells) for sc in ('S02','S03','S04')))
        tot=max(worst.values())
        ok_s = tot<=wa+1e-9; ok_d = sl<=wd+1e-9
        # end reaction (3-span: interior 1.1wL)
        R_int=1.1*tot*L_FT; R_end=0.4*tot*L_FT
        ERCAP={22:1180,20:1520,18:2310,16:3080}[g]
        if not ok_s: errs.append('%s gravity strength %.1f > %.1f'%(zid,tot,wa))
        if not ok_d: errs.append('%s deflection load %.1f > %.1f'%(zid,sl,wd))
        if R_int>ERCAP: errs.append('%s reaction %.0f > %d'%(zid,R_int,ERCAP))
        gov=max(worst,key=lambda k:worst[k])
        upd=max(UMAP[j,i] for j,i in cells); upc=uplift_cap(g,z['n'])
        if upd>upc+1e-9: errs.append('%s uplift %.1f > %.1f'%(zid,upd,upc))
        out[zid]=dict(grav_demand=tot,grav_cap=wa,defl_load=sl,defl_cap=wd,grav_gov=gov,worst=worst,upl_demand=upd,upl_cap=upc,area_cells=len(cells))
    return out, errs
# ---------------- diaphragm ----------------
WX,WY=118.0,152.0
WSEIS=18.0+(0.2*PF if PF>30 else 0.0)
FPX=0.44*1.25/3.25*WSEIS*BX*BY/1000.0
OMEGA0=2.0
def cell_props(zones,Z):
    G=np.zeros((NY,NX)); PHISN=np.zeros((NY,NX))
    for j in range(NY):
        for i in range(NX):
            zid=Z[j,i]
            if zid is None: continue
            z=zones[zid]
            G[j,i]=gp_formula(z['g'],z['n'],z['typ'],z['ns'])
            PHISN[j,i]=0.7*sn_formula(z['g'],z['n'],z['typ'],z['ns'])
    return G,PHISN
def lateral_cases():
    cases=[]
    cases.append(('S05','W','x',0.0,1.0))
    cases.append(('S05','W','x',+0.15*BY,0.75)); cases.append(('S05','W','x',-0.15*BY,0.75))
    cases.append(('S06','W','y',0.0,1.0))
    cases.append(('S06','W','y',+0.15*BX,0.75)); cases.append(('S06','W','y',-0.15*BX,0.75))
    for e in (+0.05*BY,-0.05*BY): cases.append(('S07','E','x',e,1.0))
    for e in (+0.05*BX,-0.05*BX): cases.append(('S08','E','y',e,1.0))
    return cases
def run_lateral(zones,Z,ecc_mode='linear',edge_mode='separate',verbose=False):
    G,PHISN=cell_props(zones,Z)
    PGm=panel_G(G)
    bars=fem.build_bars(edge_mode)
    K,springs=fem.assemble(PGm,bars,1e-6)
    Kinv_solve=lambda F: np.linalg.solve(K,F)
    results={}
    for (sc,kind,d,ecc,fac) in lateral_cases():
        if kind=='W':
            F=loads_wind(d, WX if d=='x' else WY, ecc_ft=ecc, factor=fac)
        else:
            F=loads_seismic(d, FPX, ecc_ft=ecc, mode=ecc_mode)
        u=Kinv_solve(F)
        res=post(u,bars,springs,PGm,F,1e-6)
        results[(sc,ecc,fac)]=(res,u,F,d)
    return results,bars,PGm,G,PHISN
def lat_summary(results,bars,PGm,G,PHISN):
    from analyze import line_forces
    from defl import defl_measures
    summ={}
    # cell shear demand: panel q applies to all cells of panel
    cellq={}
    for key,(res,u,F,d) in results.items():
        sc=key[0]
        q=res['q_plf']
        cq=np.zeros((NY,NX))
        for jp in range(NYn-1):
            for i in range(NXn-1):
                cq[5*jp:5*jp+5,i]=abs(q[jp,i])
        cellq[sc]=np.maximum(cellq.get(sc,np.zeros((NY,NX))),cq)
        lf=line_forces(res,bars)
        if d=='x': chord_lines=[('x',0.0),('x',240.0)]; fr=[(n,v) for n,v in FRAMES.items() if v[0]=='X']
        else: chord_lines=[('y',0.0),('y',180.0)]; fr=[(n,v) for n,v in FRAMES.items() if v[0]=='Y']
        chord=max(abs(dd['total']) for (lid,pos),dd in lf.items() if lid in chord_lines)
        chord_edge=max(abs(dd['edge']) for (lid,pos),dd in lf.items() if lid in chord_lines)
        coll=0.0; coll_edge=0.0
        for (lid,pos),dd in lf.items():
            for n,(dr,line,f,t,k) in fr:
                lt='y' if dr=='X' else 'x'
                if lid==(lt,line) and (f-30-1e-6)<=pos<=(t+30+1e-6):
                    coll=max(coll,abs(dd['total'])); coll_edge=max(coll_edge,abs(dd['edge']))
        dmm=defl_measures(u,res,d)
        s=summ.setdefault(sc,dict(q=0,chord=0,coll=0,chord_edge=0,coll_edge=0,defl=0,adve=0,reg=0,umax=0,frames={}))
        s['q']=max(s['q'],np.abs(q).max()); s['chord']=max(s['chord'],chord); s['coll']=max(s['coll'],coll)
        s['chord_edge']=max(s['chord_edge'],chord_edge); s['coll_edge']=max(s['coll_edge'],coll_edge)
        s['defl']=max(s['defl'],max(dmm['m2'],dmm['m3'],dmm['m4'])); s['umax']=max(s['umax'],dmm['umax'])
        s['adve']=max(s['adve'],dmm['adve']); s['reg']=max(s['reg'],res['reg_frac'])
        for n,v in res['frame_forces'].items():
            s['frames'][n]=max(s['frames'].get(n,0),abs(v))
    return summ,cellq
def check_lateral(zones,Z,ecc_mode='linear',verbose=False):
    results,bars,PGm,G,PHISN=run_lateral(zones,Z,ecc_mode)
    summ,cellq=lat_summary(results,bars,PGm,G,PHISN)
    errs=[]
    for sc,s in summ.items():
        if s['defl']>1.60: errs.append('%s deflection %.2f > 1.60'%(sc,s['defl']))
        if s['chord']>38.0: errs.append('%s chord %.1f > 38'%(sc,s['chord']))
        amp = OMEGA0 if sc in ('S07','S08') else 1.0
        if s['coll']*amp>58.0: errs.append('%s collector(amp %.0f) %.1f > 58'%(sc,amp,s['coll']*amp))
        if s['reg']>0.02: errs.append('%s regularisation %.3f'%(sc,s['reg']))
    # shear check per cell
    zone_shear={}
    for sc,cq in cellq.items():
        bad=(cq>PHISN+1e-6)&(~OM)
        if bad.any():
            jj,ii=np.where(bad)
            worst=max(zip(jj,ii),key=lambda t: cq[t]/max(PHISN[t],1e-9))
            errs.append('%s shear exceed in %d cells, worst x=%d y=%d q=%.0f cap=%.0f'%(sc,bad.sum(),6*worst[1],6*worst[0],cq[worst],PHISN[worst]))
    for zid in zones:
        m=(Z==zid)
        zone_shear[zid]={sc:float(cq[m].max()) for sc,cq in cellq.items()}
    return summ,cellq,zone_shear,errs,(results,bars,PGm,G,PHISN)
# ---------------- cost ----------------
RATE={22:3.05,20:3.48,18:4.42}
def cost(zones,Z):
    c_area=0; c_sf=0; c_sl=0; nsf=0; nsl=0; areas={}
    for zid,z in zones.items():
        A=36.0*np.sum(Z==zid)
        areas[zid]=A
        c_area+=A*RATE[z['g']]
        lines=A/(3.0*6.0)
        nsf+=lines*z['n']; nsl+=lines*z['ns']
        c_sf+=lines*z['n']*1.35
        c_sl+=lines*z['ns']*(1.15 if z['typ']=='SCREW-10' else 0.32)
    gages=set(z['g'] for z in zones.values()); pats=set((z['n'],z['typ'],z['ns']) for z in zones.values())
    nrect=sum(len(z['rects']) for z in zones.values())
    ind=900*len(zones)+260*nrect+4800*len(gages)+1400*len(pats)
    return dict(total=c_area+c_sf+c_sl+ind, area=c_area, fasteners=c_sf, sidelaps=c_sl, indirect=ind, nsf=nsf, nsl=nsl, areas=areas)
def evaluate(zones, closed=False, ecc_mode='linear', lateral=True, verbose=True):
    dm=build_demands(closed)
    Z,errs=rules(zones)
    if any('overlap' in e or 'uncovered' in e or 'off grid' in e for e in errs):
        return dict(errs=errs)
    gout,e2=check_gravity(zones,Z,dm); errs+=e2
    out=dict(Z=Z,grav=gout)
    if lateral:
        summ,cellq,zone_shear,e3,raw=check_lateral(zones,Z,ecc_mode)
        errs+=e3; out.update(lat=summ,cellq=cellq,zone_shear=zone_shear,raw=raw)
    out['cost']=cost(zones,Z); out['errs']=errs
    if verbose:
        print('COST %.0f'%out['cost']['total'], {k:round(v) for k,v in out['cost'].items() if k in ('area','fasteners','sidelaps','indirect')})
        if lateral:
            for sc,s in sorted(out['lat'].items()):
                print('  %s q=%.0f defl=%.2f (umax %.2f adve %.2f) chord=%.1f coll=%.1f reg=%.1e'%(sc,s['q'],s['defl'],s['umax'],s['adve'],s['chord'],s['coll'],s['reg']), {k:round(v,1) for k,v in s['frames'].items()})
        for e in errs: print('  ERR',e)
    return out
def show_zones(Z):
    ids=sorted(set(v for v in Z.flatten() if v is not None))
    sym={zid:'ABCDEFGHIJKLMNOPQRSTUVWXYZ'[k] for k,zid in enumerate(ids)}
    for j in range(NY-1,-1,-1):
        print('%3d '%(6*j)+''.join(' ' if Z[j,i] is None else sym[Z[j,i]] for i in range(NX)))
    print(sym)
