import numpy as np
from drifts import scenario_bands
NX,NY=40,30
def band_cell_max(b, cx0,cx1,cy0,cy1, closed=False):
    if b['peak']<=0 or b['w']<=0: return 0.0
    if b['axis']=='x':
        a0,a1 = cx0,cx1; l0,l1 = cy0,cy1
    else:
        a0,a1 = cy0,cy1; l0,l1 = cx0,cx1
    la,lb = b['lat']
    # lateral overlap
    if closed:
        if l1 < la or l0 > lb: return 0.0
    else:
        if l1 <= la or l0 >= lb: return 0.0
    f=b['pos']; w=b['w']
    if b['sgn']>0: d0, d1 = a0-f, a1-f      # distance range of the cell along the drift axis
    else: d0, d1 = f-a1, f-a0
    # band occupies d in [0, w]
    if closed:
        if d1 < 0 or d0 > w: return 0.0
    else:
        if d1 <= 0 or d0 >= w: return 0.0
    dmin=max(0.0,d0)
    return b['peak']*(1-dmin/w)
def cell_drift_exact(sc, closed=False):
    bands=[b for b in scenario_bands(sc) if b['peak']>0]
    out=np.zeros((NY,NX))
    for j in range(NY):
        for i in range(NX):
            cx0,cx1,cy0,cy1=6*i,6*i+6,6*j,6*j+6
            m=0.0
            for b in bands:
                v=band_cell_max(b,cx0,cx1,cy0,cy1,closed)
                if v>m: m=v
            out[j,i]=m
    return out
